"조금 전까지 시끄러웠던 분위기가 자연스럽게 조용해진다.":"The noisy mood of a moment ago naturally grows quiet.",
"이번에는 가롤로도 함께 걷는다. 그러나 문 앞에서 사람들 사이로 섞인다.":"This time Carlo walks with us too. But at the door, he blends into the crowd.",
"한국. 이탈리아. 필리핀. 프랑스.":"Korea. Italy. The Philippines. France.",
"여러 나라의 청년들이 한자리에 앉는다.":"Young people from many countries sit together.",
"누군가는 성호를 긋고, 누군가는 고개를 숙이고, 누군가는 성체등을 바라본다.":"Some make the Sign of the Cross, some bow their heads, some gaze at the sanctuary lamp.",
"우리의 언어는 다릅니다.":"Our languages are different.",
"우리의 모습도 다릅니다.":"The way we look is different.",
"하지만 우리가 부르는 분은 한 분입니다.":"But the One we call upon is one.",
"함께 기도합니다.":"Let us pray together.",
"예수님,\n\n세상의 모든 청소년과 청년들을\n축복해주세요.\n\n서로 다른 우리가\n서로를 두려워하지 않고\n친구가 되게 해주세요.\n\n우리의 말과 모습과 문화가 달라도\n서로에게 있는 좋은 것을\n발견하게 해주세요.\n\n우리가 함께 웃고,\n함께 도우며,\n함께 기도하게 해주세요.\n\n그리고 우리 본당과 우리의 삶이\n찾아오는 사람을\n따뜻하게 맞아들이는 곳이 되게 해주세요.\n\n우리 모두가\n언제나 당신과 함께 걷게 해주세요.\n\n아멘.":"Jesus,\n\nbless all the teenagers and young people\nof the world.\n\nThough we are different,\nlet us not fear one another\nbut become friends.\n\nThough our words, looks and cultures differ,\nhelp us discover\nthe good in one another.\n\nLet us laugh together,\nhelp one another,\nand pray together.\n\nAnd let our parish and our lives\nbecome places that warmly welcome\nall who come.\n\nLet us all\nalways walk with You.\n\nAmen.",
